/* ================= 市场时段 ================= */
function isUSDST(d) {
  var y = d.getFullYear();
  var m1 = new Date(y,2,1), n1 = new Date(y,10,1);
  var start = new Date(y,2, 8 + (7-m1.getDay())%7);   // 3月第2个周日
  var end   = new Date(y,10, 1 + (7-n1.getDay())%7);  // 11月第1个周日
  return d >= start && d < end;
}
/* 返回 pre / regular / post / dead / closed（按北京时间） */
function usSession() {
  var n = new Date(), day = n.getDay(), t = n.getHours()*60 + n.getMinutes();
  var dst = isUSDST(n);
  var preS = dst? 960:1020, regS = dst? 1290:1350, regE = dst? 240:300, postE = dst? 480:540;
  if (day===0 || day===6) return 'closed';
  if (day===1 && t < preS) return 'closed';           // 周一白天前美股未开
  if (t >= preS && t < regS && day>=1 && day<=5) return 'pre';
  if (t >= regS && day>=1 && day<=5) return 'regular';
  if (t < regE && day>=2 && day<=6) return 'regular'; // 周二至周六凌晨
  if (t >= regE && t < postE && day>=2 && day<=6) return 'post';
  return 'dead';
}
function cnTrading() {
  var n = new Date(), day = n.getDay(), t = n.getHours()*100 + n.getMinutes();
  if (day===0||day===6) return false;
  return (t>=930&&t<=1130)||(t>=1300&&t<=1500);
}
function statusText() {
  var us = usSession();
  var usText = {pre:'美股盘前', regular:'美股交易中', post:'美股盘后', dead:'美股休市', closed:'美股休市'}[us];
  if (cnTrading()) return 'A股交易中 · ' + usText;
  return usText;
}

