/* ================= 交互 ================= */
function setView(v){
  curView=v;
  ['home','etf','mkt','mine'].forEach(function(x){
    document.getElementById('view-'+x).style.display = x===v?'block':'none';
  });
  document.querySelectorAll('nav .ni').forEach(function(n){
    n.classList.toggle('on', n.dataset.v===v);
  });
  render();
  if(v==='etf'){
    refreshEtfInfo().then(render);
    /* 立即补拉ETF行情，不等下一个15s刷新周期 */
    var need=ETF_LIST.filter(function(e){ return !quotes[etfQuoteCode(e.code)]; })
      .map(function(e){ return etfQuoteCode(e.code); });
    if(need.length) getQuotes(need).then(function(q){
      Object.keys(q).forEach(function(k){ quotes[k]=q[k]; });
      render();
    }).catch(function(){});
  }
}
/* 筛选：市场分类单选（cat）+ 可申购/自选开关（与分类取交集） */
function toggleFilter(k){
  if(k==='all'){ flt={ buy:true, fav:true, idx:true, act:true }; }
  else flt[k]=!flt[k];
  lsSet(LS_FILTER, flt);
  syncFilterUi();
  renderHome();
}
function syncFilterUi(){
  document.getElementById('ckAll').classList.toggle('on', fltAll());
  document.getElementById('ckBuy').classList.toggle('on', !!flt.buy);
  document.getElementById('ckFav').classList.toggle('on', !!flt.fav);
  document.getElementById('ckIdx').classList.toggle('on', !!flt.idx);
  document.getElementById('ckAct').classList.toggle('on', !!flt.act);
}
var SORTS=['default','desc','asc','ah','ahAsc','ytd','ytdAsc','custom'];
var SORT_LABEL={ 'default':'默认', 'desc':'涨幅↓', 'asc':'涨幅↑', 'ah':'AH↓', 'ahAsc':'AH↑', 'ytd':'今年↓', 'ytdAsc':'今年↑', 'custom':'自定义' };
function ahSum(f){ return f.ah ? (+f.ah.a||0)+(+f.ah.hk||0) : -1; }
function cycleSort(){
  var i=SORTS.indexOf(curSort);
  curSort=SORTS[(i+1)%SORTS.length];
  lsSet(LS_SORT, curSort);
  document.getElementById('sortBtn').textContent='排序 · '+SORT_LABEL[curSort];
  renderHome();
}
/* ================= 基金详情模块（历史表现 / 走势图 / 估值对比） ================= */
var RANGES=[['w1','近一周',5],['m1','近一月',22],['m3','近三月',66],['m6','近六月',120],['y1','近一年',250],['y3','近三年',750],['y5','近五年',1250],['all','全部',100000]];
var fundHist={}, chartRange={};
var benchmarkRows=null, benchmarkJob=null, benchmarkLoadedAt=0, benchmarkError='';
/* 腾讯沪深300日线。按年份分段读取，覆盖老基金的“全部历史”区间。 */
function loadBenchmark(){
  if(benchmarkRows && Date.now()-benchmarkLoadedAt<6*3600000) return Promise.resolve(benchmarkRows);
  if(benchmarkJob) return benchmarkJob;
  var year=new Date().getFullYear(), windows=[];
  for(var start=2005;start<=year;start+=8) windows.push([start,Math.min(start+7,year)]);
  benchmarkRows=null;
  benchmarkError='';
  benchmarkJob=Promise.all(windows.map(function(w){
    var param='sh000300,day,'+w[0]+'-01-01,'+w[1]+'-12-31,2000,qfq';
    var url='https://web.ifzq.gtimg.cn/appstock/app/fqkline/get?param='+encodeURIComponent(param);
    return fetch(url,{mode:'cors',credentials:'omit'}).then(function(resp){
      if(!resp.ok) throw new Error('沪深300历史行情请求失败');
      return resp.json();
    }).then(function(payload){
      var rows=payload&&payload.data&&payload.data.sh000300&&payload.data.sh000300.day;
      if(!Array.isArray(rows)) throw new Error('沪深300历史行情格式异常');
      return rows.map(function(x){ return {d:x[0],v:+x[2]}; })
        .filter(function(x){return /^\d{4}-\d\d-\d\d$/.test(x.d)&&isFinite(x.v)&&x.v>0;});
    });
  })).then(function(parts){
    var byDate={};
    parts.forEach(function(part){part.forEach(function(row){byDate[row.d]=row;});});
    benchmarkRows=Object.keys(byDate).sort().map(function(d){return byDate[d];});
    if(benchmarkRows.length<2) throw new Error('沪深300历史行情不足');
    benchmarkLoadedAt=Date.now(); benchmarkJob=null;
    return benchmarkRows;
  }).catch(function(err){
    benchmarkError=err.message||'沪深300历史行情暂不可用'; benchmarkJob=null;
    throw err;
  });
  return benchmarkJob;
}
var LS_ESTSNAP='fe2_estsnap';
/* 每日估值快照：每次刷新把当前实时估值按日期落盘（同日覆盖，留最终估值），供"历史估值对比"使用 */
function snapshotEstimates(){
  try{
    var snap=lsGet(LS_ESTSNAP,{});
    var n=new Date(), pad=function(x){return x<10?'0'+x:''+x;};
    var key=n.getFullYear()+'-'+pad(n.getMonth()+1)+'-'+pad(n.getDate());
    var day=snap[key]||(snap[key]={});
    funds.forEach(function(f){
      var e=estimate(f).live;
      if(e!==null&&!isNaN(e)) day[f.code]=+e.toFixed(3);
    });
    var cutoff=Date.now()-90*86400000;
    Object.keys(snap).forEach(function(k){ var t=new Date(k+'T00:00:00').getTime(); if(!isNaN(t)&&t<cutoff) delete snap[k]; });
    lsSet(LS_ESTSNAP, snap);
  }catch(e){}
}
/* 历史数据：阶段涨幅 + 净值序列（1小时缓存） */
function ensureHist(code){
  var h=fundHist[code];
  if(h && !h.failed && Date.now()-h.ts<3600000) return Promise.resolve(h);
  return loadFundSeries(code,true).then(function(r){
    fundHist[code]=r;
    return r;
  });
}
/* 基金累计净值与沪深300收盘价按相同日期、相同起点换算成期间收益率。 */
function comparableSeries(nav, indexRows){
  if(!nav || !indexRows || !indexRows.length) return [];
  var out=[], j=0, index=null, baseFund=null, baseIndex=null;
  var lastIndexDate=indexRows[indexRows.length-1].d;
  nav.forEach(function(row){
    var value=+row.cum;
    if(!isFinite(value)||value<=0||row.d>lastIndexDate) return;
    while(j<indexRows.length && indexRows[j].d<=row.d){ index=indexRows[j]; j++; }
    if(!index) return;
    if(baseFund===null){ baseFund=value; baseIndex=index.v; }
    out.push({d:row.d,fund:(value/baseFund-1)*100,index:(index.v/baseIndex-1)*100});
  });
  return out;
}
function comparisonChartSvg(nav, indexRows){
  var points=comparableSeries(nav,indexRows);
  if(points.length<2) return '<div class="hm-empty">两组数据没有足够的共同日期，暂无法比较</div>';
  var W=640,H=220,PL=40,PR=18,PT=16,PB=29;
  var values=[]; points.forEach(function(p){values.push(p.fund,p.index);}); values.push(0);
  var min=Math.min.apply(null,values),max=Math.max.apply(null,values);
  if(max-min<0.1){min-=1;max+=1;}
  var pad=(max-min)*0.1; min-=pad; max+=pad;
  var firstTime=Date.parse(points[0].d+'T00:00:00Z'), lastTime=Date.parse(points[points.length-1].d+'T00:00:00Z');
  var x=function(p){return PL+(W-PL-PR)*(Date.parse(p.d+'T00:00:00Z')-firstTime)/(lastTime-firstTime);};
  var y=function(v){return PT+(H-PT-PB)*(max-v)/(max-min);};
  var line=function(key){return points.map(function(p,i){return (i?'L':'M')+x(p).toFixed(1)+','+y(p[key]).toFixed(1);}).join('');};
  var last=points[points.length-1];
  var grid=[0,.5,1].map(function(t){
    var val=max-(max-min)*t, yy=y(val).toFixed(1);
    return '<line class="cmp-grid" x1="'+PL+'" y1="'+yy+'" x2="'+(W-PR)+'" y2="'+yy+'"/>'
      +'<text class="cmp-axis" x="'+(PL-7)+'" y="'+(+yy+4)+'" text-anchor="end">'+(val>0?'+':'')+val.toFixed(0)+'%</text>';
  }).join('');
  return '<div class="comparison-chart">'
    +'<div class="cmp-legend"><span><i class="cmp-fund"></i>本基金 <b>'+fmtPct(last.fund)+'</b></span><span><i class="cmp-index"></i>沪深300 <b>'+fmtPct(last.index)+'</b></span></div>'
    +'<svg class="hm-chart" viewBox="0 0 '+W+' '+H+'" role="img" aria-label="本基金与同期沪深300的收益率走势对比">'
    +grid+'<line class="cmp-zero" x1="'+PL+'" y1="'+y(0).toFixed(1)+'" x2="'+(W-PR)+'" y2="'+y(0).toFixed(1)+'"/>'
    +'<path class="cmp-index-line" d="'+line('index')+'"/><path class="cmp-fund-line" d="'+line('fund')+'"/>'
    +'<circle class="cmp-index-end" cx="'+x(last).toFixed(1)+'" cy="'+y(last.index).toFixed(1)+'" r="3"/>'
    +'<circle class="cmp-fund-end" cx="'+x(last).toFixed(1)+'" cy="'+y(last.fund).toFixed(1)+'" r="3"/>'
    +'<text class="cmp-axis" x="'+PL+'" y="'+(H-6)+'">'+points[0].d+'</text>'
    +'<text class="cmp-axis" x="'+(W-PR)+'" y="'+(H-6)+'" text-anchor="end">'+last.d+'</text></svg>'
    +'<div class="cmp-note">同一起点归一为 0% · 按基金净值日期对齐沪深300最近收盘价</div></div>';
}
/* 历史估值对比表：估值快照 × 实际净值涨跌 */
function estCompareHtml(f, navAll){
  var snap=lsGet(LS_ESTSNAP,{});
  var actByDate={};
  navAll.forEach(function(x){ if(!isNaN(x.pct)) actByDate[x.d]=x.pct; });
  var rows=[];
  Object.keys(snap).forEach(function(d){
    var est=snap[d][f.code];
    if(est===undefined || actByDate[d]===undefined) return;
    rows.push({ d:d, est:est, act:actByDate[d], dev:est-actByDate[d] });
  });
  rows.sort(function(a,b){ return a.d<b.d?1:-1; });
  /* 平均偏差统计（全部记录） */
  var sum=0, absSum=0;
  rows.forEach(function(x){ sum+=x.dev; absSum+=Math.abs(x.dev); });
  var avg=rows.length?sum/rows.length:null, avgAbs=rows.length?absSum/rows.length:null;
  var title='<div class="hm-title" style="margin-top:12px"><span>历史估值对比</span></div>';
  if(!rows.length){
    return title+'<div class="hm-empty">积累几日估值记录后展示（每日刷新自动记录）</div>';
  }
  return title
    +'<div class="hm-stat">共 '+rows.length+' 条记录 · 平均偏差（估值−实际） <b class="'+cls(avg)+'">'+fmtPct(avg)+'</b> · 平均绝对偏差 '+fmtPct(avgAbs)+'</div>'
    +'<table class="hold hm-cmp"><tr><th>日期</th><th>估值</th><th>实际</th><th>偏离</th></tr>'
    +rows.map(function(x){
      return '<tr><td>'+x.d+'</td>'
        +'<td class="'+cls(x.est)+'">'+fmtPct(x.est)+'</td>'
        +'<td class="'+cls(x.act)+'">'+fmtPct(x.act)+'</td>'
        +'<td class="'+cls(x.dev)+'">'+fmtPct(x.dev)+'</td></tr>';
    }).join('')+'</table>';
}
function histModulesHtml(f){
  var h=fundHist[f.code];
  if(!h) return '<div class="hm-sec"><div class="hm-empty">历史数据加载中…</div></div>';
  if(h.failed) return '<div class="hm-sec"><div class="hm-empty">历史数据加载失败，重新展开卡片可再试</div></div>';
  if(!h.nav || h.nav.length<2) return '<div class="hm-sec"><div class="hm-empty">暂无历史净值数据</div></div>';
  var r=chartRange[f.code]||'y1';
  var cnt=250;
  RANGES.forEach(function(x){ if(x[0]===r) cnt=x[2]; });
  var win=h.nav.slice(-cnt);
  var tabs='<div class="hm-tabs">'+RANGES.map(function(x){
    return '<span class="hm-tab'+(x[0]===r?' on':'')+'" onclick="setChartRange(\''+f.code+'\',\''+x[0]+'\')">'+x[1]+'</span>';
  }).join('')+'</div>';
  /* ① 累计净值数值保留；走势图以同期收益率与沪深300比较。 */
  var last=win[win.length-1];
  var lastCum=!isNaN(last.cum)?last.cum:last.nav;
  var lastPct=isNaN(last.pct)?null:last.pct;
  var html='<div class="hm-sec">'
    +'<div class="hm-title"><span>净值走势 · 同期沪深300对比</span>'+tabs+'</div>'
    +'<div class="hm-nav-tip">最新累计净值 <b>'+(isNaN(lastCum)?'--':lastCum.toFixed(4))+'</b>'
    +(lastPct!==null?' <span class="'+cls(lastPct)+'">'+fmtPct(lastPct)+'</span>':'')
    +'</div>'
    +(benchmarkRows?comparisonChartSvg(win,benchmarkRows):'<div class="hm-empty">'+(benchmarkError?'沪深300数据暂不可用：'+benchmarkError:'正在加载同期沪深300数据…')+'</div>');
  /* ② 历史估值对比（含平均偏差统计） */
  html+=estCompareHtml(f, h.nav);
  /* ③ 基金历史表现（点击与累计净值走势图联动；今年为期间收益不联动） */
  var perMap=[['Y','近1月','m1'],['3Y','近3月','m3'],['6Y','近6月','m6'],['1N','近1年','y1'],['3N','近3年','y3'],['5N','近5年','y5'],['JN','今年',''],['LN','全部','all']];
  html+='<div class="hm-title" style="margin-top:12px"><span>基金历史表现</span></div><div class="hm-perf">'
    +perMap.map(function(p){
      var v=h.period[p[0]];
      var linked=p[2]?(' onclick="setChartRange(\''+f.code+'\',\''+p[2]+'\')" title="点击查看对应区间走势"'):'';
      var on=p[2]&&chartRange[f.code]===p[2]?' on':'';
      return '<div class="hp'+on+'"'+linked+'><div class="hp-l">'+p[1]+'</div><div class="hp-v '+cls(v)+'">'+fmtPct(v)+'</div></div>';
    }).join('')+'</div>';
  return html+'</div>';
}
function setChartRange(code, r){
  chartRange[code]=r;
  renderHome();
}
function toggle(code){
  if(Date.now()<(suppressClickUntil||0)) return;
  expanded[code]=!expanded[code];
  /* 点击卡片消除限额变动高亮 */
  var tf=funds.filter(function(x){ return x.code===code; })[0];
  if(tf && tf.limitAlert){ delete tf.limitAlert; saveFunds(); }
  if(expanded[code] && !(fundHist[code] && !fundHist[code].failed && Date.now()-fundHist[code].ts<3600000)){
    ensureHist(code).then(function(){ renderHome(); }).catch(function(){ fundHist[code]={ts:0,failed:true}; renderHome(); });
  }
  if(expanded[code] && !benchmarkRows) loadBenchmark().then(function(){renderHome();}).catch(function(){renderHome();});
  renderHome();
}
function toggleFav(code){
  funds.forEach(function(f){ if(f.code===code) f.fav=!f.fav; });
  saveFunds(); render();
}
function delFund(code,name){
  if(!confirm('删除 '+(name||code)+'（'+code+'）？')) return;
  funds=funds.filter(function(f){ return f.code!==code; });
  saveFunds(); render();
}
/* ---- 长按/拖动排序（拖动自动切换为「自定义」排序） ---- */
var dragCode=null, dropCode=null, suppressClickUntil=0;
function dragStart(e){
  var card=e.target.closest('.card'); if(!card) return;
  dragCode=card.dataset.code; e.dataTransfer.effectAllowed='move';
  try{ e.dataTransfer.setData('text/plain', dragCode); }catch(_){}
  card.classList.add('dragging');
}
function dragOver(e){
  e.preventDefault(); e.dataTransfer.dropEffect='move';
  var card=e.target.closest('.card'); if(!card||card.dataset.code===dragCode) return;
  if(dropCode&&dropCode!==card.dataset.code){ var prev=document.querySelector('.card[data-code="'+dropCode+'"]'); if(prev) prev.classList.remove('drop-target'); }
  dropCode=card.dataset.code; card.classList.add('drop-target');
}
function dragLeave(e){
  var card=e.target.closest('.card'); if(card&&card.dataset.code===dropCode){ card.classList.remove('drop-target'); dropCode=null; }
}
function dropCard(e){
  e.preventDefault();
  var card=e.target.closest('.card'); if(!card||!dragCode||card.dataset.code===dragCode){ dragEnd(e); return; }
  commitReorder(dragCode, card.dataset.code);
}
function dragEnd(e){
  document.querySelectorAll('.card.dragging,.card.drop-target').forEach(function(c){ c.classList.remove('dragging'); c.classList.remove('drop-target'); });
  dragCode=null; dropCode=null;
}
function commitReorder(fromCode, toCode){
  var codes=funds.map(function(f){ return f.code; });
  var fi=codes.indexOf(fromCode), ti=codes.indexOf(toCode);
  if(fi<0||ti<0) return;
  codes.splice(fi<ti ? ti-1 : ti,0,codes.splice(fi,1)[0]);
  var byCode={}; funds.forEach(function(f){ byCode[f.code]=f; });
  funds=codes.map(function(c){ return byCode[c]; });
  curSort='custom'; lsSet(LS_SORT,'custom'); lsSet(LS_ORDER, codes);
  document.getElementById('sortBtn').textContent='排序 · 自定义';
  saveFunds(); render();
}
/* 触屏：长按卡片后拖动，经过目标即实时换位，松手提交 */
var tDrag=null;
function cardTouchStart(e){
  var card=e.target.closest('.card'); if(!card) return;
  var y=e.touches[0].clientY;
  tDrag={ code:card.dataset.code, y0:y, moved:false, timer:setTimeout(function(){ if(tDrag) tDrag.armed=true; },350) };
}
function cardTouchMove(e){
  if(!tDrag||!tDrag.armed) return;
  e.preventDefault();
  var y=e.touches[0].clientY, dy=y-tDrag.y0;
  if(Math.abs(dy)<8) return;
  tDrag.moved=true;
  var el=document.elementFromPoint(e.touches[0].clientX, y);
  var card=el&&el.closest?el.closest('.card'):null;
  if(!card||card.dataset.code===tDrag.code) return;
  var list=document.getElementById('list');
  var cur=list.querySelector('.card[data-code="'+tDrag.code+'"]');
  var cards=Array.prototype.slice.call(list.querySelectorAll('.card'));
  if(cards.indexOf(cur)<cards.indexOf(card)) card.after(cur); else card.before(cur);
}
function cardTouchEnd(){
  if(!tDrag) return;
  clearTimeout(tDrag.timer);
  if(tDrag.moved){
    suppressClickUntil=Date.now()+400;
    var codes=Array.prototype.map.call(document.querySelectorAll('#list .card'), function(c){ return c.dataset.code; });
    var byCode={}; funds.forEach(function(f){ byCode[f.code]=f; });
    var reordered=codes.concat(funds.map(function(f){return f.code;}).filter(function(c){ return codes.indexOf(c)<0; }));
    funds=reordered.map(function(c){ return byCode[c]; });
    curSort='custom'; lsSet(LS_SORT,'custom'); lsSet(LS_ORDER, reordered);
    document.getElementById('sortBtn').textContent='排序 · 自定义';
    saveFunds(); render();
  }
  tDrag=null;
}
document.addEventListener('touchmove', function(e){ if(tDrag&&tDrag.armed) e.preventDefault(); }, {passive:false});

function onCardCtx(e,code,name){
  e.preventDefault();
  delFund(code,name);
  return false;
}
function resetAll(){
  if(!confirm('恢复为默认基金列表？')) return;
  funds=seedFromDefaults();
  saveFunds(); refresh();
}

/* 搜索 */
function searchFunds(kw) {
  return jsonp('https://fundsuggest.eastmoney.com/FundSearch/api/FundSearchAPI.ashx?m=1&key='+encodeURIComponent(kw))
    .then(function(d){
      return (d.Datas||[]).filter(function(x){return x.CATEGORY===700;}).map(function(x){
        var b=x.FundBaseInfo||{};
        return { code:x.CODE, name:x.NAME, ftype:b.FTYPE||'', nav:b.DWJZ };
      });
    });
}
/* 去重为A份额；若直接搜代码命中非A份额，再用基名搜一次找A份额 */
function searchAOnly(kw) {
  return searchFunds(kw).then(function(list){
    var out = dedupeAClass(list);
    var exact = list.filter(function(x){ return x.code===kw; })[0];
    if (exact && exact._cls && exact._cls!=='A') {
      var baseKey = exact._key.split('|')[0];
      return searchFunds(baseKey).then(function(list2){
        var hit = dedupeAClass(list2).filter(function(x){ return x._key===exact._key && x._cls==='A'; })[0];
        if (hit) {
          out = out.filter(function(x){ return x._key!==exact._key; });
          out.unshift(hit);
        }
        return out;
      });
    }
    return out;
  });
}
var debounce=null, searchResults=[], searchRequestId=0;
function closeSearch(clearInput){
  searchRequestId++;
  if(debounce){ clearTimeout(debounce); debounce=null; }
  searchResults=[];
  var box=document.getElementById('results');
  box.style.display='none'; box.innerHTML='';
  if(clearInput) document.getElementById('kw').value='';
}
document.getElementById('kw').addEventListener('input', function(e){
  var kw=e.target.value.trim();
  if(debounce) clearTimeout(debounce);
  var requestId=++searchRequestId;
  var box=document.getElementById('results');
  renderHome();
  if(!kw){ closeSearch(false); return; }
  debounce=setTimeout(function(){
    if(requestId!==searchRequestId) return;
    box.style.display='block';
    box.innerHTML='<div class="hint">搜索中…</div>';
    searchAOnly(kw)
      .then(function(list){
        if(requestId!==searchRequestId || document.getElementById('kw').value.trim()!==kw) return;
        searchResults=list.slice(0,15);
        box.innerHTML=searchResults.length? searchResults.map(function(it,i){
          return '<div class="r-row" onclick="addFund('+i+')"><div><div class="r-name">'+it.name+'</div>'
            +'<div class="r-sub">'+it.code+' · '+it.ftype+'</div></div>'
            +'<div class="r-add">'+(funds.some(function(f){return f.code===it.code;})?'查看':'+ 添加')+'</div></div>';
        }).join('') : '<div class="hint">没有找到相关基金</div>';
      }).catch(function(){
        if(requestId===searchRequestId) box.innerHTML='<div class="hint">搜索失败，请重试</div>';
      });
  }, 350);
});
document.getElementById('kw').addEventListener('keydown', function(e){
  if(e.key==='Escape'){ closeSearch(true); renderHome(); this.blur(); }
});
document.addEventListener('pointerdown', function(e){
  if(!e.target.closest('.search-box')) closeSearch(false);
});
var toastTimer=null;
function toast(msg){
  var t=document.getElementById('toast');
  if(!t){ t=document.createElement('div'); t.id='toast'; document.body.appendChild(t); }
  t.textContent=msg; t.className='toast show';
  if(toastTimer) clearTimeout(toastTimer);
  toastTimer=setTimeout(function(){ t.className='toast'; }, 2200);
}
function addFund(i){
  var it=searchResults[i]; if(!it) return;
  var exists=funds.some(function(f){return f.code===it.code;});
  var d = FUNDS_DEFAULT.filter(function(x){ return x.code===it.code; })[0];
  if(!exists){
    try {
      funds.unshift({ code:it.code, name:it.name, ftype:it.ftype, nav:it.nav, coef:0.90,
        ah:(d&&d.ah)||IDX_AH[it.code]||null, scope:d?d.scope||null:null });
      saveFunds();
    } catch(e){ toast('添加失败：'+(e.message||e)); return; }
  }
  closeSearch(true);
  toggleFilter('all');
  var card=document.querySelector('#list .card[data-code="'+it.code+'"]');
  if(card) card.scrollIntoView({block:'center',behavior:'smooth'});
  toast(exists?'已在列表中：'+it.name:'已添加：'+it.name);
  if(!exists) refresh();
}

/* ================= 启动 ================= */
function expandHoldings(list){
  return (list||[]).map(function(s){ return { code:s[0], name:s[1], weight:s[2], texch:s[3] }; });
}
function seedFromDefaults(){
  return FUNDS_DEFAULT.map(function(f){ return { code:f.code, name:f.name, ftype:f.ftype, coef:f.coef||0.90, ah:f.ah||idxAhOf(f), scope:f.scope||null,
    scopeDate:f.scopeDate||'', scopeSrc:f.scopeSrc||'', direct:f.direct||null, idxName:f.idxName||'', src:f.src||(f.holdings?'full':''),
    holdings:expandHoldings(f.holdings), reportDate:f.reportDate||'',
    limitClasses:f.limitClasses||null, limitTs:f.limitClasses?Date.now():0 }; });
}
function migrateFunds(list){
  var merged=false;
  list.forEach(function(f){
    /* 非A份额 → 迁移到A份额（同一只基金，持仓一致） */
    var m=A_SHARE_MAP[f.code];
    if(m){
      if(!list.some(function(x){ return x!==f && x.code===m.code; })){
        f.code=m.code; f.name=m.name; f.scope=m.scope; f.limit=null; f.limitClasses=null; f.limitTs=0; merged=true;
      }
    }
    /* 老数据补充内置基金的AH比例/限购口径/全部持仓 */
    var d=FUNDS_DEFAULT.filter(function(x){ return x.code===f.code; })[0];
    if(d){
      if(!f.ah&&d.ah){ f.ah=d.ah; merged=true; }
      if(!f.ah){ var ia=idxAhOf(f); if(ia){ f.ah=ia; merged=true; } }
      if(!f.scope&&d.scope){ f.scope=d.scope; merged=true; }
      if(d.src==='idx'&&f.src!=='idx'){ f.src='idx'; f.coef=d.coef||1; f.idxName=d.idxName||''; f.holdings=expandHoldings(d.holdings); f.reportDate=''; f.ah=idxAhOf(f); merged=true; }
      if(d.holdings&&d.src!=='idx'&&f.src!=='full'&&f.src!=='idx'){ f.holdings=expandHoldings(d.holdings); f.reportDate=d.reportDate; f.src='full'; merged=true; }
      if(d.limitClasses&&!f.limitClasses){ f.limitClasses=d.limitClasses; f.limitTs=Date.now(); merged=true; }
      if(d.scopeDate&&!f.scopeDate){ f.scopeDate=d.scopeDate; merged=true; }
      /* 表格口径（共同限额基金列）为权威标准：覆盖旧解析结果 */
      if(d.scopeSrc==='table'&&(f.scopeSrc!=='table'||f.scope!==d.scope)){ f.scope=d.scope; f.scopeDate=d.scopeDate; f.scopeSrc='table'; merged=true; }
      /* 直销限额以内置数据为准 */
      if(d.direct&&(!f.direct||f.direct.max!==d.direct.max)){ f.direct=d.direct; merged=true; }
      /* 持仓修正版本：内置持仓修复后覆盖本地旧值（同报告期内容也可能修正） */
      if(d.holdingsVer&&f.holdingsVer!==d.holdingsVer&&d.holdings){
        f.holdings=expandHoldings(d.holdings); f.reportDate=d.reportDate; f.ah=d.ah||null;
        if(f.src!=='idx') f.src='full';
        f.holdingsVer=d.holdingsVer; f.holdingsTs=0; merged=true;
      }
      /* 直销专供份额标注以内置数据为准 */
      if(d.limitClasses&&f.limitClasses){
        d.limitClasses.forEach(function(dc){
          if(!dc.directOnly) return;
          var fc=f.limitClasses.filter(function(x){ return x.code===dc.code; })[0];
          if(fc&&!fc.directOnly){ fc.directOnly=true; merged=true; }
        });
      }
    }
  });
  /* 去重：同一代码只留一个 */
  var seen={}, out=[];
  list.forEach(function(f){ if(!seen[f.code]){ seen[f.code]=1; out.push(f); } else merged=true; });
  return { list:out, merged:merged };
}
funds=lsGet(LS_FUNDS, null);
if(!funds||!funds.length){
  funds=seedFromDefaults();
  saveFunds();
} else {
  var mig=migrateFunds(funds);
  funds=mig.list;
  if(mig.merged) saveFunds();
}
usClose=lsGet(LS_USCLOSE, {});
curSort=lsGet(LS_SORT,'default');
document.getElementById('sortBtn').textContent='排序 · '+SORT_LABEL[curSort];
refresh();
startTimer();
